INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 3052, 'តាមចំណុចមួយ គេអាចគូសបន្ទាត់ត្រង់បានប៉ុន្មាន?', NULL, '["ច្រើនរាប់មិនអស់", "បី", "ពីរ", "មួយគត់"]', 0, NULL, 1, 'mcq', 'កាត់តាមចំណុចមួយ មានបន្ទាត់ច្រើនរាប់មិនអស់។', 'សញ្ញាណដំបូងនៃធរណីមាត្រ', 'easy', 1, '7', 'សញ្ញាណដំបូងនៃធរណីមាត្រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 3053, 'ចំណុច \(3\) ចំណុចស្ថិតនៅលើបន្ទាត់តែមួយ។ គូសបានអង្កត់ដែលមានចុងជាចំណុចទាំងនេះប៉ុន្មាន?', NULL, '["\\(6\\)", "\\(1\\)", "\\(4\\)", "\\(3\\)"]', 3, NULL, 1, 'mcq', '\(\dfrac{3\times2}{2} = 3\)។', 'សញ្ញាណដំបូងនៃធរណីមាត្រ', 'easy', 1, '7', 'សញ្ញាណដំបូងនៃធរណីមាត្រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 3054, 'ចំណុច \(B\) ស្ថិតនៅចន្លោះ \(A\) និង \(C\) លើអង្កត់ \(AC\)។ \(AB = 12\ \text{cm}\) និង \(BC = 46\ \text{cm}\)។ រក \(AC\)៖', NULL, '["\\(60\\ \\text{cm}\\)", "\\(29\\ \\text{cm}\\)", "\\(58\\ \\text{cm}\\)", "\\(34\\ \\text{cm}\\)"]', 2, NULL, 1, 'mcq', '\(AC = AB + BC\)។', 'សញ្ញាណដំបូងនៃធរណីមាត្រ', 'easy', 1, '7', 'សញ្ញាណដំបូងនៃធរណីមាត្រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 3055, '\(I\) ជាចំណុចកណ្តាលនៃ \(AB\) ហើយ \(AB = 18\ \text{cm}\)។ \(AI\) ស្មើប៉ុន្មាន?', NULL, '["\\(18\\ \\text{cm}\\)", "\\(6\\ \\text{cm}\\)", "\\(36\\ \\text{cm}\\)", "\\(9\\ \\text{cm}\\)"]', 3, NULL, 1, 'mcq', '\(AI = \dfrac{AB}{2} = 9\)។', 'សញ្ញាណដំបូងនៃធរណីមាត្រ', 'easy', 1, '7', 'សញ្ញាណដំបូងនៃធរណីមាត្រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 3056, 'បន្ទាត់ពីរផ្សេងគ្នាប្រសព្វគ្នាបានមានចំណុចរួមអតិបរមាប៉ុន្មាន?', NULL, '["\\(2\\)", "\\(1\\)", "ច្រើនរាប់មិនអស់", "\\(0\\)"]', 1, NULL, 2, 'mcq', 'បន្ទាត់ពីរផ្សេងគ្នាមានចំណុចរួមមិនលើសមួយ។', 'សញ្ញាណដំបូងនៃធរណីមាត្រ', 'medium', 1, '7', 'សញ្ញាណដំបូងនៃធរណីមាត្រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 3057, 'ចំណុច \(5\) ចំណុចស្ថិតនៅលើបន្ទាត់តែមួយ។ គូសបានអង្កត់ដែលមានចុងជាចំណុចទាំងនេះប៉ុន្មាន?', NULL, '["\\(6\\)", "\\(20\\)", "\\(10\\)", "\\(5\\)"]', 2, NULL, 2, 'mcq', '\(\dfrac{5\times4}{2} = 10\)។', 'សញ្ញាណដំបូងនៃធរណីមាត្រ', 'medium', 1, '7', 'សញ្ញាណដំបូងនៃធរណីមាត្រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 3058, 'ចំណុច \(B\) ស្ថិតនៅចន្លោះ \(A\) និង \(C\) លើអង្កត់ \(AC\)។ \(AB = 7.5\ \text{cm}\) និង \(BC = 12.5\ \text{cm}\)។ រក \(AC\)៖', NULL, '["\\(5\\ \\text{cm}\\)", "\\(20\\ \\text{cm}\\)", "\\(22\\ \\text{cm}\\)", "\\(10\\ \\text{cm}\\)"]', 1, NULL, 2, 'mcq', '\(AC = AB + BC\)។', 'សញ្ញាណដំបូងនៃធរណីមាត្រ', 'medium', 1, '7', 'សញ្ញាណដំបូងនៃធរណីមាត្រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 3059, 'ចំណុច \(A, B, C, D\) រៀងតាមលំដាប់លើបន្ទាត់ ហើយ \(AB = CD\)។ អ្វីដែលត្រឹមត្រូវ?', NULL, '["\\(AD = BC\\)", "\\(AC = BD\\)", "\\(AC = AB\\)", "\\(BC = CD\\)"]', 1, NULL, 2, 'mcq', '\(AC = AB + BC = CD + BC = BD\)។', 'សញ្ញាណដំបូងនៃធរណីមាត្រ', 'medium', 1, '7', 'សញ្ញាណដំបូងនៃធរណីមាត្រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 3060, '\(I\) ជាចំណុចកណ្តាលនៃ \(AB\) ហើយ \(J\) ជាចំណុចកណ្តាលនៃ \(AI\)។ \(AB\) ស្មើប៉ុន្មានដងនៃ \(AJ\)?', NULL, '["\\(3\\)", "\\(2\\)", "\\(8\\)", "\\(4\\)"]', 3, NULL, 2, 'mcq', '\(AJ = \dfrac{AI}{2} = \dfrac{AB}{4}\)។', 'សញ្ញាណដំបូងនៃធរណីមាត្រ', 'medium', 1, '7', 'សញ្ញាណដំបូងនៃធរណីមាត្រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 3061, 'អង្កត់ \(AF\) ត្រូវបានចែកជា \(5\) អង្កត់ស្មើគ្នា ហើយ \(AB = 1.2\ \text{cm}\)។ \(AF\) ស្មើ៖', NULL, '["\\(1.2\\ \\text{cm}\\)", "\\(0.24\\ \\text{cm}\\)", "\\(6\\ \\text{cm}\\)", "\\(7.2\\ \\text{cm}\\)"]', 2, NULL, 2, 'mcq', '\(AF = 5 \times 1.2 = 6\)។', 'សញ្ញាណដំបូងនៃធរណីមាត្រ', 'medium', 1, '7', 'សញ្ញាណដំបូងនៃធរណីមាត្រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 3062, 'បន្ទាត់ \(xy\) មានចំណុច \(M\) នៅលើវា។ ចំណុច \(M\) ចែកបន្ទាត់ \(xy\) ជាកន្លះបន្ទាត់ប៉ុន្មាន?', NULL, '["\\(3\\)", "\\(4\\)", "\\(2\\)", "\\(1\\)"]', 2, NULL, 2, 'mcq', '\(Mx\) និង \(My\)។', 'សញ្ញាណដំបូងនៃធរណីមាត្រ', 'medium', 1, '7', 'សញ្ញាណដំបូងនៃធរណីមាត្រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 3063, 'មានចំណុច \(4\) ចំណុច ដែលគ្មានបីចំណុចណារត់ត្រង់គ្នា។ គូសបានបន្ទាត់ត្រង់ប៉ុន្មាន ដែលកាត់តាមពីរចំណុច?', NULL, '["\\(3\\)", "\\(4\\)", "\\(7\\)", "\\(6\\)"]', 3, NULL, 3, 'mcq', 'រៀងគូ \(\dfrac{n(n-1)}{2} = 6\)។', 'សញ្ញាណដំបូងនៃធរណីមាត្រ', 'hard', 1, '7', 'សញ្ញាណដំបូងនៃធរណីមាត្រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 3064, 'ចំណុច \(A, B, C, D\) រៀងតាមលំដាប់លើបន្ទាត់ \(\Delta\) ដោយ \(AB = CD = 3\ \text{cm}\) និង \(BC = 5\ \text{cm}\)។ \(AD\) ស្មើប៉ុន្មាន?', NULL, '["\\(11\\ \\text{cm}\\)", "\\(6\\ \\text{cm}\\)", "\\(8\\ \\text{cm}\\)", "\\(13\\ \\text{cm}\\)"]', 0, NULL, 3, 'mcq', '\(3 + 5 + 3 = 11\)។', 'សញ្ញាណដំបូងនៃធរណីមាត្រ', 'hard', 1, '7', 'សញ្ញាណដំបូងនៃធរណីមាត្រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 3065, 'អង្កត់ \(MN = 18\ \text{cm}\)។ \(I\) ជាចំណុចមួយនៃ \(MN\) (មិនមែនចំណុចកណ្តាល)។ \(A, B\) ជាចំណុចកណ្តាលនៃ \(MI\) និង \(IN\)។ \(AB\) ស្មើ៖', NULL, '["\\(4.5\\ \\text{cm}\\)", "\\(18\\ \\text{cm}\\)", "\\(9\\ \\text{cm}\\)", "\\(6\\ \\text{cm}\\)"]', 2, NULL, 3, 'mcq', '\(AB = \dfrac{MI}{2} + \dfrac{IN}{2} = \dfrac{MN}{2} = 9\)។', 'សញ្ញាណដំបូងនៃធរណីមាត្រ', 'hard', 1, '7', 'សញ្ញាណដំបូងនៃធរណីមាត្រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 3066, 'ផ្លូវត្រង់មួយប្រវែង \(600\ \text{m}\) ដាំបង្គោលភ្លើងរៀងរាល់ \(50\ \text{m}\) ម្តង ដោយមានបង្គោលដើមផ្លូវនិងចុងផ្លូវ។ ត្រូវការបង្គោលប៉ុន្មានដើម?', NULL, '["\\(12\\)", "\\(14\\)", "\\(13\\)", "\\(600\\)"]', 2, NULL, 3, 'mcq', '\(600 \div 50 = 12\) ចន្លោះ ហេតុនេះមាន \(12 + 1 = 13\) ដើម។', 'សញ្ញាណដំបូងនៃធរណីមាត្រ', 'pisa', 1, '7', 'សញ្ញាណដំបូងនៃធរណីមាត្រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 3067, 'ក្រុមហ៊ុនស្ថាបនាបង្គោលរបងតាមបន្ទាត់ត្រង់ប្រវែង \(90\ \text{m}\) ចម្ងាយរវាងបង្គោលជាប់គ្នា \(3\ \text{m}\) ហើយមានបង្គោលទាំងចុងទាំងពីរ។ ត្រូវការបង្គោលប៉ុន្មាន?', NULL, '["\\(30\\)", "\\(32\\)", "\\(31\\)", "\\(93\\)"]', 2, NULL, 3, 'mcq', '\(90 \div 3 + 1 = 31\)។', 'សញ្ញាណដំបូងនៃធរណីមាត្រ', 'pisa', 1, '7', 'សញ្ញាណដំបូងនៃធរណីមាត្រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 3068, 'ចំណុច \(A, B, C, D\) រៀងតាមលំដាប់លើបន្ទាត់ \(\Delta\) ដោយ \(AB = CD = 3\ \text{cm}\) និង \(BC = 5\ \text{cm}\)។ គណនា \(AC\), \(BD\) និង \(AD\)។', NULL, '[]', 0, NULL, 5, 'writing', '\(AC = AB + BC = 3 + 5 = 8\ \text{cm}\) (2 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 3069, 'អង្កត់ \(XY = 30\ \text{cm}\)។ \(I\) ជាចំណុចមួយនៃ \(XY\) (មិនមែនចំណុចកណ្តាល)។ \(M, N\) ជាចំណុចកណ្តាលនៃ \(XI\) និង \(IY\)។ គណនា \(MN\)។', NULL, '[]', 0, NULL, 5, 'writing', '\(MI = \dfrac{XI}{2}\) និង \(IN = \dfrac{IY}{2}\) (2 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 3070, 'គេមានបីចំណុច \(X, Y, Z\) តាមលំដាប់លើបន្ទាត់ \(\Delta\) ហើយ \(S\) ជាចំណុចកណ្តាលនៃ \(YZ\)។ បើ \(XY = 8\ \text{cm}\) និង \(XZ = 20\ \text{cm}\) គណនា \(YZ\), \(YS\) និង \(XS\)។', NULL, '[]', 0, NULL, 5, 'writing', '\(YZ = 20 - 8 = 12\ \text{cm}\) (2 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 3071, 'មានចំណុច \(6\) ចំណុចលើបន្ទាត់តែមួយ។ ក. គូសបានអង្កត់ប៉ុន្មាន? ខ. បើបន្ទាត់ \(6\) ចំណុចនេះជា \(A,B,C,D,E,F\) តាមលំដាប់ \(AB=BC=CD=DE=EF=2\ \text{cm}\) រកប្រវែង \(AF\) និងអង្កត់វែងបំផុត។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. \(\dfrac{6 \times 5}{2} = 15\) អង្កត់ (2 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 3072, 'ផ្លូវត្រង់មួយប្រវែង \(600\ \text{m}\) ដាំបង្គោលភ្លើងរៀងរាល់ \(50\ \text{m}\) ដោយមានបង្គោលដើមផ្លូវនិងចុងផ្លូវ។ ក. ប៉ុន្មានដើម? ខ. បង្គោលមួយដើមថ្លៃ \(120\,000\) ៛ ថ្លៃសរុប?', NULL, '[]', 0, NULL, 5, 'writing', 'ក. ចន្លោះ \(600 \div 50 = 12\) ដូច្នេះបង្គោល \(12 + 1 = 13\) ដើម (3 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 3073, 'ខ្យងមួយនៅបាតអណ្តូងជម្រៅ \(8\ \text{m}\)។ ពេលយប់វារឡើង \(4\ \text{m}\) ពេលថ្ងៃធ្លាក់ចុះ \(2\ \text{m}\)។ ក. ក្រោយ \(1\) យប់និង \(1\) ថ្ងៃ វានៅកម្ពស់ប៉ុន្មាន? ខ. ឡើងដល់មាត់អណ្តូងក្នុងប៉ុន្មានយប់?', NULL, '[]', 0, NULL, 5, 'writing', 'ក. ក្រោយថ្ងៃទី ១ \(4 - 2 = 2\ \text{m}\) (1 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 3074, 'សុខជិះម៉ូតូចេញពីភូមិ \(A\) ទៅភូមិ \(B\) ហើយជួបសៅដែលជិះកង់ចេញពី \(B\) ទៅ \(A\)។ ចម្ងាយពី \(A\) ដល់កន្លែងជួប ស្មើ \(\dfrac{2}{3}\) នៃចម្ងាយ \(AB\)។ បើ \(AB = 36\ \text{km}\) ក. សុខធ្វើដំណើរបានប៉ុន្មាន km? ខ. សៅធ្វើដំណើរបានប៉ុន្មាន? គ. សុខជិះបានចម្ងាយច្រើនជាងសៅប៉ុន្មានដង?', NULL, '[]', 0, NULL, 5, 'writing', 'ក. \(\dfrac{2}{3} \times 36 = 24\ \text{km}\) (2 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 3075, 'ម្ជុលដេរមួយប្រវែង \(35\ \text{mm}\)។ រោងចក្រមានខ្សែលួស \(52.5\ \text{m}\) ហើយ \(20\%\) ខូចក្នុងការផលិត។ ក. ខ្សែប្រើបានប៉ុន្មានម៉ែត្រ? ខ. ផលិតម្ជុលបានប៉ុន្មានដើម?', NULL, '[]', 0, NULL, 5, 'writing', 'ក. \(52.5 \times 0.8 = 42\ \text{m}\) (2 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 3076, 'ក្រុមហ៊ុនដាំដើមឈើតាមមាត់ផ្លូវត្រង់ប្រវែង \(480\ \text{m}\) រៀងរាល់ \(8\ \text{m}\) ម្តង ដោយដាំទាំងចុងទាំងពីរ។ ក. ដាំបានប៉ុន្មានដើម? ខ. ដើមឈើមួយដើមថ្លៃ \(5\,000\) ៛ អស់ប្រាក់ប៉ុន្មាន? គ. បើដាំផ្លូវទាំងសងខាង សរុបប៉ុន្មានដើម?', NULL, '[]', 0, NULL, 5, 'writing', 'ក. ចន្លោះ \(480 \div 8 = 60\) ដូច្នេះដើមឈើ \(60 + 1 = 61\) ដើម (2 ពិន្ទុ)
